#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    // Length limit: allow up to 1024 characters (0x400). If longer, report TOO_LONG.
    if (strlen(s1) > 1024 || strlen(s2) > 1024) {
        puts("TOO_LONG");
        return 0;
    }
    int cnt1[256] = {0};
    int cnt2[256] = {0};
    // Count characters of first string, ignoring spaces, case‑insensitive for letters.
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ') continue;
        if (c >= 'A' && c <= 'Z') c = c + ('a' - 'A');
        cnt1[c]++;
    }
    // Count characters of second string.
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ') continue;
        if (c >= 'A' && c <= 'Z') c = c + ('a' - 'A');
        cnt2[c]++;
    }
    // Compare frequency tables.
    int not_anagram = 0;
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) {
            not_anagram = 1;
            break;
        }
    }
    if (not_anagram)
        puts("NOT_ANAGRAM");
    else
        puts("ANAGRAM");
    return 0;
}
